#include <vector>
#include <string>

using namespace std;

class Solution {
public:
    vector<string> removeComments(vector<string>& source) {
        vector<string> res;
        string line;
        bool inBlock = false;
        for (auto& src : source) {
            for (int i = 0; i < src.size(); ++i) {
                if (!inBlock && i + 1 < src.size() && src[i] == '/' && src[i + 1] == '*') {
                    inBlock = true;
                    ++i;
                } else if (inBlock && i + 1 < src.size() && src[i] == '*' && src[i + 1] == '/') {
                    inBlock = false;
                    ++i;
                } else if (!inBlock && i + 1 < src.size() && src[i] == '/' && src[i + 1] == '/') {
                    break;
                } else if (!inBlock) {
                    line += src[i];
                }
            }
            if (!inBlock && !line.empty()) {
                res.push_back(line);
                line.clear();
            }
        }
        return res;
    }
};
